// node tests/paul-roe-memorial.mjs
// Public-only memorial requirements. Never read the private archive repository.
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
// Source layout: game code lives in src/, houses.json is generated by `npm run build`.
const read=p=>readFileSync(new URL('../'+(p==='houses.json'?'dist/public/houses.json':'src/'+p),import.meta.url),'utf8');
const source=read('world/paul-roe-tribute.js');
const {honourPaulRoe,isPaulRoeMemorial,PAUL_ROE_COORDINATES}=
  new Function(source.replace(/^export /gm,'')+'\nreturn {honourPaulRoe,isPaulRoeMemorial,PAUL_ROE_COORDINATES}')( );
const input=JSON.parse(read('houses.json')).houses;
assert.equal(input.length,188,'Do not remove or duplicate houses');
assert.deepEqual([...PAUL_ROE_COORDINATES].sort(),['C2','K3']);
const altered=input.map(honourPaulRoe),memorials=altered.filter(isPaulRoeMemorial);
assert.equal(memorials.length,2,'Keep both Paul tribute locations');
assert.equal(altered.filter(x=>x.memorial).length,2);
assert.equal(altered.filter((x,i)=>x!==input[i]).length,2,'Other 186 houses must remain unchanged');
const propKinds=new Set([...read('world/props.js').matchAll(/def\('([^']+)'/g)].map(x=>x[1]));
const forbidden=/\b(dice|d20|goblin|crystal|fortune|battle|lucky dip|treasure chest|dragon|combat)\b/i;
const goodURLs=[/^https:\/\/joshualparris\.github\.io\/Paul-Roe\//,
 /^https:\/\/github\.com\/joshualparris\/Paul-Roe\/blob\/main\/Paul%20Roe%20Order%20of%20Service\.pdf$/,
 /^https:\/\/www\.theoutbackhistorian\.com\.au\//,
 /^https:\/\/archival\.sl\.nsw\.gov\.au\/Details\/archive\/110318820$/];
for(const h of memorials){
 assert(h.memorial,'Memorial flag missing');
 assert(h.summary.includes('Paul Roe'),h.name);
 assert(!forbidden.test(h.summary),h.name+' has RPG theme');
 assert(h.int.rooms.length>1,h.name+' has no tribute galleries');
 assert(h.int.rooms.every(r=>!['Bathroom and laundry','Bedroom','Living room','Repository Archive','Discovery games'].includes(r.name)),
  h.name+' has an irrelevant autogenerated room');
 for(const r of h.int.rooms)for(const [type,label,action] of r.props){
   assert(propKinds.has(type),h.name+' uses unknown 3D prop '+type);
   assert(!forbidden.test(type+' '+label+' '+JSON.stringify(action||'')),
     'Out of place fantasy exhibit in '+h.coordinate+' '+r.name);
   assert(type!=='resident','Memorials must never impersonate Paul or invent staff');
   if(action) {
     assert(['info','link'].includes(action.do),'No games in tribute rooms');
     if(action.url)assert(goodURLs.some(x=>x.test(action.url)),
       'Use only public approved memorial/story links: '+action.url);
   }
 }
}
const k=memorials.find(h=>h.coordinate==='K3'),c=memorials.find(h=>h.coordinate==='C2');
assert.equal(k.int.rooms.length,6,'Six themed public memorial galleries expected');
assert.equal(c.int.rooms.length,2,'Private archive should be a modest public reflection');
assert(/faith|Cornerstone/i.test(k.int.rooms.map(r=>r.name).join(' ')+' '+k.int.rooms.flatMap(r=>r.props.map(p=>p[2]?.text||'')).join(' ')));
assert(!k.int.rooms.some(r=>r.name==='Bathroom and laundry'));
const main=read('main.js'),interior=read('world/interior.js');
assert(main.includes('data.houses.map(honourPaulRoe)'),'Public game must load authored tribute');
assert(main.includes('resident && !base.memorial'),'Random household must not take over a memorial');
assert(main.includes('h.memorial ? null : createFloorStack'),'No autogenerated fantasy upper floors');
assert(interior.includes('!hasBed && !house.memorial'),'No added memorial bedrooms');
assert(interior.includes('sprite.userData.labelRoom = l.room'),'Labels need an owning room');
assert(main.includes('s.userData.labelRoom === currentRoom'),'Hide labels across walls');
assert(interior.includes('(r.z0 + r.z1) / 2'),'Room labels are centered in their own room');
console.log('PASS: both Paul Roe memorial houses use sourced, private-safe tribute rooms; no fantasy games or misleading bathroom labels; other 186 homes preserved');
